    debug!(target: "transport", "usb pull {} -> {:?}", remote, local);
    let transport = USBTransport::new(self.vendor_id, self.product_id)
        .map_err(|e| XdbError::Adb(format!("USB reconnect for pull: {}", e)))?;
    // ...
